const input = $json.body ?? $json;
const uuid = (v) => typeof v === 'string' && /^[0-9a-f]{8}-[0-9a-f-]{27,}$/i.test(v);
if (input.workflowKey !== "crm.lead.create" || input.contract !== "ancfz-v2-stage-action-v1") throw new Error('Unsupported workflow contract.');
for (const k of ['actionId','tenantId','sessionId','eventId','correlationId','opportunityId']) if (!uuid(input[k])) throw new Error('Missing server-issued '+k);
for (const k of ['catalogVersionId','idempotencyKey']) if (typeof input[k] !== 'string' || !input[k].trim()) throw new Error('Missing action correlation '+k);
if (input.actionKey !== "lead.create") throw new Error('Unexpected action key.');
if (!Number.isInteger(input.actionRevision) || input.actionRevision < 1) throw new Error('Missing action revision.');
if (!Number.isInteger(input.attempt) || input.attempt < 1) throw new Error('Missing attempt.');
return [{json: {actionId:input.actionId,tenantId:input.tenantId,sessionId:input.sessionId,opportunityId:input.opportunityId,catalogVersionId:input.catalogVersionId,idempotencyKey:input.idempotencyKey,actionKey:input.actionKey,actionRevision:input.actionRevision,eventId:input.eventId,correlationId:input.correlationId,attempt:input.attempt,workflowKey:input.workflowKey,contract:input.contract}}];

const rows = $json.items;
if (!Array.isArray(rows) || rows.length !== 1) throw new Error('Expected one authorized Node action; no bulk execution.');
const action = rows[0];
const env = $('Validate Dispatch Envelope').first().json;
if (action.workflowKey !== "crm.lead.create" || action.actionKey !== "lead.create" || action.stageKey !== "lead_generation" || action.contract !== env.contract) throw new Error('Stage/action contract mismatch.');
for (const k of ['actionId','tenantId','sessionId','eventId','correlationId']) if (action[k] !== env[k]) throw new Error('Claim correlation mismatch: '+k);
if (action.attempt !== env.attempt || !Number.isInteger(action.actionRevision) || action.actionRevision < 1) throw new Error('Stale action revision or attempt.');
for (const k of ['opportunityId','catalogVersionId','idempotencyKey','actionKey','approvedPayload']) if (!action[k]) throw new Error('Missing approved Node field: '+k);
if (action.actionKey !== "lead.create") throw new Error('Action identity mismatch.');
if (action.providerEnabled !== true || action.v2Authorized !== true || action.purposeConsentVerified !== true || action.actionConfirmationVerified !== true) throw new Error('Node did not explicitly authorize this V2 side effect.');
if (typeof action.approvedPayload !== 'object' || Array.isArray(action.approvedPayload)) throw new Error('Approved payload missing.');
return [{json:action}];

const action = $('Require V2 Stage Authorization').first().json;
const provider = $('Call Provider - Configure Credential').first().json;
const readback = $json;
for (const key of ['actionId','tenantId','sessionId','opportunityId','catalogVersionId','idempotencyKey','actionKey','actionRevision','eventId','correlationId','attempt']) if (action[key] === undefined || action[key] === null) throw new Error('Missing trusted action correlation: '+key);
if (typeof provider.leadId !== 'string' || provider.leadId.length === 0) throw new Error('Provider did not return a Lead identifier.');
return [{json:{actionId:action.actionId,tenantId:action.tenantId,sessionId:action.sessionId,opportunityId:action.opportunityId,catalogVersionId:action.catalogVersionId,idempotencyKey:action.idempotencyKey,actionKey:action.actionKey,actionRevision:action.actionRevision,stageKey:'lead_generation',workflowKey:'crm.lead.create',providerRecordId:provider.leadId,providerReadback:readback,eventId:action.eventId,correlationId:action.correlationId,attempt:action.attempt}}];

const source = $('Require V2 Stage Authorization').first().json;
const result = $json;
if (result.accepted !== true || result.evidenceTier !== 'provider_record_verified' || result.stageKey !== "lead_generation") throw new Error('Node has not independently verified provider state.');
for (const key of ['actionId','tenantId','sessionId','opportunityId','catalogVersionId','idempotencyKey','actionKey','actionRevision','eventId','correlationId','attempt']) if (result[key] !== source[key]) throw new Error('Node attestation scope mismatch: '+key);
if (typeof result.providerRecordRef !== 'string' || !/^[A-Za-z0-9][A-Za-z0-9._:-]{0,199}$/.test(result.providerRecordRef)) throw new Error('Invalid provider attestation record reference.');
return [{json:{...result,executionReference:$execution.id}}];
